(()=>{'use strict';
const form=document.querySelector('[data-program-search]');if(!form)return;const input=form.querySelector('input'),result=document.querySelector('[data-search-results]'),message=document.querySelector('[data-search-status]');let index,request=0;
const clean=s=>String(s||'').normalize('NFKD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,' ').trim(),aliases={'nvda':'nvidia','ryson':'ryzen','ryzan':'ryzen','mother board':'motherboard','bios compatibility':'bios support','fist boot':'first boot'};
const normalize=s=>{let v=String(s||'').slice(0,120).toLowerCase();for(const [from,to] of Object.entries(aliases))v=v.replaceAll(from,to);return clean(v)};
function distance(a,b){if(Math.abs(a.length-b.length)>2)return 3;let prev=Array.from({length:b.length+1},(_,i)=>i);for(let i=1;i<=a.length;i++){const next=[i];for(let j=1;j<=b.length;j++)next[j]=Math.min(next[j-1]+1,prev[j]+1,prev[j-1]+(a[i-1]===b[j-1]?0:1));prev=next}return prev[b.length]}
async function show(value,push){const turn=++request,q=normalize(value);input.value=value.slice(0,120);if(push){const url=new URL(location.href);q?url.searchParams.set('q',input.value):url.searchParams.delete('q');history.pushState(null,'',url)}result.replaceChildren();if(!q){message.textContent='Enter an exact model, a question, or a tool name.';return}message.textContent='Searching on this device…';try{index ||= fetch('/data/search-index.json').then(r=>{if(!r.ok)throw Error('Search is temporarily unavailable.');return r.json()});const rows=await index;if(turn!==request)return;const words=q.split(' '),ranked=rows.map(row=>{const names=[row.title,...(row.aliases||[])].map(normalize),exact=names.includes(q),text=names.join(' '),all=words.every(w=>text.includes(w)),partial=names.some(n=>n.includes(q)),fuzzy=!all&&!partial&&words.every(w=>w.length>3&&text.split(' ').some(t=>distance(w,t)<=1));return{row,score:exact?100:words.every(w=>normalize(row.title).includes(w))?85:all?70:partial?50:fuzzy?20:0}}).filter(r=>r.score).sort((a,b)=>b.score-a.score||a.row.title.localeCompare(b.row.title)).slice(0,40);const unique=new Set();for(const {row,score}of ranked){if(unique.has(row.url))continue;unique.add(row.url);const li=document.createElement('li'),a=document.createElement('a'),p=document.createElement('p');a.href=row.url;a.textContent=row.title;p.textContent=row.kind+(score===20?' · similar spelling':'');li.append(a,p);result.append(li)}message.textContent=unique.size?(ranked.length===40?'Showing the first 40 matches.':unique.size+' results.')+' Product, guide and tool types are shown beside each result.':'No matching result. Try the model number, fewer words, or browse hardware and Build School.';}catch(e){index=null;message.textContent=e.message+' Browse the navigation or retry.'}}
form.addEventListener('submit',e=>{e.preventDefault();show(input.value,true)});window.addEventListener('popstate',()=>show(new URLSearchParams(location.search).get('q')||'',false));show(new URLSearchParams(location.search).get('q')||'',false);
})();
